<?php
$pageUrl=function(int $target) use($tab,$period,$dateFrom,$dateTo,$search,$statusFilter,$actionFilter,$severityFilter){return url('/studio/notifications?'.http_build_query(array_filter(['tab'=>$tab,'page'=>$target,'period'=>$period,'date_from'=>$dateFrom,'date_to'=>$dateTo,'q'=>$search,'status'=>$statusFilter,'action'=>$actionFilter,'severity'=>$severityFilter],static fn($value)=>$value!==''&&$value!==null)));};
$renderPagination=function() use($page,$pages,$total,$pageUrl){if($pages<=1)return;?><footer class="studio-list-footer"><span><?= number_format($total,0,',','.') ?> registro(s) · Página <?= $page ?> de <?= $pages ?></span><nav class="studio-pagination"><?php if($page>1):?><a class="studio-pagination_item" href="<?= $pageUrl($page-1) ?>"><ion-icon name="arrow-back-outline"></ion-icon></a><?php endif;?><?php for($i=max(1,$page-2);$i<=min($pages,$page+2);$i++):?><a class="studio-pagination_item <?= $i===$page?'studio-pagination_active':'' ?>" href="<?= $pageUrl($i) ?>"><?= $i ?></a><?php endfor;?><?php if($page<$pages):?><a class="studio-pagination_item" href="<?= $pageUrl($page+1) ?>"><ion-icon name="arrow-forward-outline"></ion-icon></a><?php endif;?></nav></footer><?php };
$hasFilters=$search!==''||$statusFilter!==''||$actionFilter!==''||$severityFilter!==''||$dateFrom!==null||$dateTo!==null||$period!==30;
?>
