        <?php if($tab==='queue'):?><fieldset><legend>Status</legend><div><?php foreach([''=>'Todos','pending'=>'Pendente','processing'=>'Processando','retry'=>'Nova tentativa','sent'=>'Enviado','failed'=>'Falhou','cancelled'=>'Cancelado'] as $value=>$label):?><label><input type="radio" name="status" value="<?= $value ?>" <?= $statusFilter===$value?'checked':'' ?>><span><?= $label ?></span></label><?php endforeach;?></div></fieldset><?php else:?><fieldset><legend>Ação</legend><div><?php foreach([''=>'Todas','create'=>'Criação','update'=>'Atualização','delete'=>'Exclusão','login'=>'Entrada','logout'=>'Saída'] as $value=>$label):?><label><input type="radio" name="action" value="<?= $value ?>" <?= $actionFilter===$value?'checked':'' ?>><span><?= $label ?></span></label><?php endforeach;?></div></fieldset><fieldset><legend>Prioridade</legend><div><?php foreach([''=>'Todas','info'=>'Informação','warning'=>'Atenção','error'=>'Erro'] as $value=>$label):?><label><input type="radio" name="severity" value="<?= $value ?>" <?= $severityFilter===$value?'checked':'' ?>><span><?= $label ?></span></label><?php endforeach;?></div></fieldset><?php endif;?>
