<?php if($tab==='queue'):?><section class="studio-panel studio-mail-queue studio-tabular-panel"><header><div><small>E-MAIL</small><h2>Fila de envio</h2></div><span class="studio-counter"><?= number_format($total,0,',','.') ?> resultado(s)</span></header><div class="studio-table-wrap"><table class="studio-table"><thead><tr><th>Destinatário</th><th>Assunto</th><th>Agendamento</th><th>Tentativas</th><th>Status</th><th></th></tr></thead><tbody><?php if(!$mailQueue):?><tr><td colspan="6">Nenhum envio corresponde aos filtros.</td></tr><?php endif;?><?php foreach($mailQueue as $mail):?><?php $mailStatus=['pending'=>'Pendente','processing'=>'Processando','retry'=>'Nova tentativa','sent'=>'Enviado','failed'=>'Falhou','cancelled'=>'Cancelado'][$mail->status]??ucfirst($mail->status);?><tr><td><strong><?= htmlspecialchars($mail->recipient_name) ?></strong><small><?= htmlspecialchars($mail->recipient_email) ?></small></td><td><?= htmlspecialchars($mail->subject) ?><?php if($mail->error_message):?><small class="studio-mail-error"><?= htmlspecialchars(mb_strimwidth($mail->error_message,0,75,'...')) ?></small><?php endif;?></td><td><?= date_fmt($mail->scheduled_at?:$mail->created_at) ?></td><td><?= (int)$mail->attempts ?>/<?= (int)$mail->max_attempts ?></td><td><span class="mail-status <?= htmlspecialchars($mail->status) ?>"><?= $mailStatus ?></span></td><td><div class="studio-mail-actions"><?php if(!in_array($mail->status,['sent','cancelled'],true)):?><form action="<?= url('/studio/notifications/mail-queue') ?>" method="post"><?= csrf_input() ?><input type="hidden" name="queue_id" value="<?= $mail->id ?>"><button name="action" value="cancel" title="Cancelar"><ion-icon name="close-circle-outline"></ion-icon></button></form><?php endif;?><?php if(in_array($mail->status,['failed','cancelled','retry'],true)):?><form action="<?= url('/studio/notifications/mail-queue') ?>" method="post"><?= csrf_input() ?><input type="hidden" name="queue_id" value="<?= $mail->id ?>"><button name="action" value="retry" title="Tentar novamente"><ion-icon name="refresh-outline"></ion-icon></button></form><?php endif;?></div></td></tr><?php endforeach;?></tbody></table></div><?php $renderPagination(); ?><footer class="studio-mail-queue-help"><ion-icon name="information-circle-outline"></ion-icon>Falhas recebem novas tentativas automáticas.</footer></section><?php endif;?>

<?php if($tab==='audit'&&$canAudit):?><section class="studio-panel studio-audit-log studio-tabular-panel"><header><div><small>RASTREABILIDADE</small><h2>Alterações recentes no sistema</h2></div><span><?= number_format($total,0,',','.') ?> resultado(s)</span></header><div class="studio-table-wrap"><table class="studio-table"><thead><tr><th>Data</th><th>Usuário</th><th>Ação</th><th>Área</th><th>Registro</th><th>Detalhes</th><th>IP</th></tr></thead><tbody><?php if(!$auditLogs):?><tr><td colspan="7">Nenhuma alteração corresponde aos filtros.</td></tr><?php endif;?><?php foreach($auditLogs as $log):?><?php $context=json_decode((string)$log->context_json,true);?><tr><td><?= date_fmt($log->created_at) ?></td><td><?= htmlspecialchars($userMap[$log->users_id]??'Sistema') ?></td><td><span class="audit-action <?= htmlspecialchars($log->action) ?>"><?= htmlspecialchars($log->action) ?></span></td><td><?= htmlspecialchars($log->entity) ?></td><td>#<?= htmlspecialchars((string)$log->entity_id) ?></td><td><?= htmlspecialchars(implode(', ',$context['changed_fields']??[]))?:'—' ?></td><td><?= htmlspecialchars((string)$log->ip)?:'—' ?></td></tr><?php endforeach;?></tbody></table></div><?php $renderPagination(); ?></section><?php endif;?>
<?php $this->start('scripts') ?><script>
document.querySelector('[data-notification-audience]')?.addEventListener('change',e=>document.querySelector('.notification-target-user')?.classList.toggle('show',e.target.value==='user'));
const studioFilterDrawer=document.querySelector('[data-filter-drawer]');
const studioToggleFilter=open=>{if(!studioFilterDrawer)return;studioFilterDrawer.classList.toggle('open',open);studioFilterDrawer.setAttribute('aria-hidden',open?'false':'true');document.body.classList.toggle('studio-filter-open',open);if(open)studioFilterDrawer.querySelector('input,button')?.focus()};
document.querySelector('[data-filter-open]')?.addEventListener('click',()=>studioToggleFilter(true));
studioFilterDrawer?.querySelectorAll('[data-filter-close]').forEach(button=>button.addEventListener('click',()=>studioToggleFilter(false)));
const studioDateInputs=studioFilterDrawer?.querySelectorAll('.studio-date-range input[type="date"]')||[];
const studioPeriodInputs=studioFilterDrawer?.querySelectorAll('input[name="period"]')||[];
studioDateInputs.forEach(input=>{input.addEventListener('change',()=>studioPeriodInputs.forEach(period=>period.checked=false));input.addEventListener('click',()=>{if(typeof input.showPicker==='function')input.showPicker()})});
studioPeriodInputs.forEach(period=>period.addEventListener('change',()=>{if(!period.checked)return;studioDateInputs.forEach(input=>input.value='')}));
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&studioFilterDrawer?.classList.contains('open'))studioToggleFilter(false)});
</script><?php $this->stop() ?>
